// Generated by `cargo run -p xtask -- lua-helpers` from the
// `native_*` helper signatures (`lua_helper_model`): do not edit. Regenerate
// to update.
//
// The Lua bridge of the host helpers the generator enables: `horizon.<name>`
// wrappers it installs, the queued actions `run_generated_action` runs after a
// handler, and the reads `generated_read` answers from the hook's host (both
// fallthroughs from the hand-written `run_action` and `read` in `lua_mods.rs`).
// Server-state helpers: the server lists stay out of `CLIENT_API`/`DRAW_API`, so a client
// state raises the server-only error for them, like the hand-written server ones;
// client-state helpers (`GENERATED_CLIENT_*`, issue 50) are installed for real on a
// client state and stubbed on a server state with the client-only error, like
// the world markers.
// The hand-written helpers it mirrors: `kick` (a player and a string, dropped
// bool), `give_experience` (the clamp-then-`as` saturating cast; every integer
// argument here saturates the same way, never `as` wrap), `teleport_player`
// (non-finite floats are a script error naming the argument). An
// entity argument is an id number (a Lua number, integral and
// non-negative) resolved through `Host::entity` to its handle; a
// position is a `{x, y, z}` table (`[i32; 3]` errors on a
// fractional or out-of-range component instead of saturating).
// A malformed script argument IS an error naming the argument; a
// host-side refusal (a `false`) is never a Lua error and never aborts
// the handler's remaining queued actions; an unresolvable player or
// an unresolvable entity is a silent no-op (actions) or nil (reads,
// as `menu_contents` and `has_permission` do).

use crate::lua_mods::uuid_of;
use horizon_client::mod_api::EquipmentSlot;
use horizon_client::mod_api::Host;
use mlua::{Lua, MultiValue, Table, Value};

/// One `EquipmentSlot` argument's Lua value: one of its eight
/// lowercase name strings (`"mainhand"`, `"offhand"`, `"head"`,
/// `"chest"`, `"legs"`, `"feet"`, `"body"`, `"saddle"`), as the
/// hooks name them, else a script error naming the helper and the
/// argument. Shared by the read and queued-action arms (the latter
/// has no `Lua` at hand for the converter itself).
fn equipment_slot_of(helper: &str, arg: &str, value: &Value) -> mlua::Result<EquipmentSlot> {
    let field = format!("{helper}.{arg}");
    match value {
        Value::String(s) => match s.to_string_lossy().as_ref() {
            "mainhand" => Ok(EquipmentSlot::MainHand),
            "offhand" => Ok(EquipmentSlot::OffHand),
            "head" => Ok(EquipmentSlot::Head),
            "chest" => Ok(EquipmentSlot::Chest),
            "legs" => Ok(EquipmentSlot::Legs),
            "feet" => Ok(EquipmentSlot::Feet),
            "body" => Ok(EquipmentSlot::Body),
            "saddle" => Ok(EquipmentSlot::Saddle),
            name => Err(mlua::Error::runtime(format!(
                "{field}: expected one of \"mainhand\", \"offhand\", \"head\", \"chest\", \"legs\", \"feet\", \"body\", \"saddle\", got {name:?}"
            ))),
        },
        other => Err(mlua::Error::runtime(format!(
            "{field}: expected a name, got {}",
            other.type_name()
        ))),
    }
}

/// One `LevelRef` argument's Lua value: its dimension id string
/// (`"minecraft:overworld"`), else a script error naming the helper
/// and the argument. Shared by the read and queued-action arms.
fn dimension_of(helper: &str, arg: &str, value: &Value) -> mlua::Result<String> {
    match value {
        Value::String(s) if !s.to_string_lossy().is_empty() => Ok(s.to_string_lossy().to_owned()),
        _ => Err(mlua::Error::runtime(format!(
            "{helper}.{arg}: expected a dimension id"
        ))),
    }
}

